// Transparent scenario illustration using ONLY hard-coded synthetic cash movements.
// It is NOT an accounting cash balance, a forecast generated by AI or a bank feed.
export const CASHFLOW_SCENARIOS=Object.freeze({
  conservative:{name:"Previdno",collectionPercent:50},
  baseline:{name:"Osnovno",collectionPercent:75},
  optimistic:{name:"Optimistično",collectionPercent:100}
});
const demoData={
  1:{
    openingCents:1245080,
    receivables:[{days:6,cents:122000},{days:15,cents:244000},{days:25,cents:91500}],
    payables:[{days:8,cents:32000},{days:17,cents:18500},{days:23,cents:21450}]
  },
  2:{
    openingCents:800000,
    receivables:[{days:12,cents:250000},{days:28,cents:100000}],
    payables:[{days:5,cents:8500},{days:18,cents:85000}]
  },
  3:{
    openingCents:540000,
    receivables:[{days:10,cents:15000},{days:21,cents:120000}],
    payables:[{days:13,cents:43000},{days:29,cents:200000}]
  }
};
export function calculateCashflowScenario(companyId,horizonDays=30,scenario="baseline"){
 if(!Number.isSafeInteger(companyId)||!Object.hasOwn(demoData,companyId))
   throw new Error("Neveljavno demonstracijsko podjetje.");
 if(![14,30].includes(horizonDays))throw new Error("Nepodprto obdobje napovedi.");
 if(!Object.hasOwn(CASHFLOW_SCENARIOS,scenario))throw new Error("Neznan scenarij.");
 const source=demoData[companyId];
 const received=source.receivables.filter(x=>x.days<=horizonDays)
   .reduce((sum,x)=>sum+x.cents,0);
 const payables=source.payables.filter(x=>x.days<=horizonDays)
   .reduce((sum,x)=>sum+x.cents,0);
 const expectedReceipts=Math.round(received*CASHFLOW_SCENARIOS[scenario].collectionPercent/100);
 const closingCents=source.openingCents+expectedReceipts-payables;
 return {
   companyId,horizonDays,scenario,
   openingCents:source.openingCents,
   grossReceivablesCents:received,
   expectedReceiptsCents:expectedReceipts,
   duePayablesCents:payables,
   closingCents,
   negativeBalance:closingCents<0,
   calculatedFrom:"fixed-synthetic-scenario"
 };
}
